// Neural Control and Coordination — generated by Claude (no source PDF supplied).
// Covers neuron structure, generation/conduction of nerve impulse, synaptic
// transmission, the central and peripheral nervous systems, reflex action, and
// the structure/function of the eye and ear.

export const NEURAL_CONTROL_COORDINATION = [
  // ---- MCQ (60) ----
  { id: 'ncc-1', type: 'mcq', question: 'The basic structural and functional unit of the nervous system is the:', options: ['Neuroglia', 'Neuron', 'Synapse', 'Nephron'], correctIndex: 1, explanation: 'The neuron is the fundamental unit responsible for generating and transmitting nerve impulses.', difficulty: 'easy' },
  { id: 'ncc-2', type: 'mcq', question: 'The branched, tree-like extensions of a neuron that receive incoming signals are called:', options: ['Axons', 'Dendrites', 'Nodes of Ranvier', 'Myelin sheath'], correctIndex: 1, explanation: 'Dendrites receive signals from other neurons and conduct them toward the cell body.', difficulty: 'easy' },
  { id: 'ncc-3', type: 'mcq', question: 'The long, single process of a neuron that carries the nerve impulse away from the cell body is the:', options: ['Dendrite', 'Axon', 'Cell body (soma)', 'Nucleus'], correctIndex: 1, explanation: 'The axon conducts the nerve impulse away from the cell body toward the axon terminal.', difficulty: 'easy' },
  { id: 'ncc-4', type: 'mcq', question: 'The fatty, insulating sheath that covers the axon of many neurons, increasing conduction speed, is the:', options: ['Node of Ranvier', 'Myelin sheath', 'Synaptic cleft', 'Neurolemma'], correctIndex: 1, explanation: 'Myelin sheath, formed by Schwann cells (PNS) or oligodendrocytes (CNS), speeds up impulse conduction.', difficulty: 'easy' },
  { id: 'ncc-5', type: 'mcq', question: 'The gaps present at regular intervals along a myelinated axon, where the myelin sheath is absent, are called:', options: ['Synapses', 'Nodes of Ranvier', 'Dendrites', 'Axon hillocks'], correctIndex: 1, explanation: 'Nodes of Ranvier are the gaps between successive myelin segments, essential for saltatory conduction.', difficulty: 'medium' },
  { id: 'ncc-6', type: 'mcq', question: 'The cells that form the myelin sheath around axons in the peripheral nervous system are called:', options: ['Oligodendrocytes', 'Schwann cells', 'Astrocytes', 'Microglia'], correctIndex: 1, explanation: 'Schwann cells wrap around peripheral axons, forming the myelin sheath there.', difficulty: 'medium' },
  { id: 'ncc-7', type: 'mcq', question: 'In the central nervous system, the myelin sheath around axons is formed by:', options: ['Schwann cells', 'Oligodendrocytes', 'Microglia', 'Ependymal cells'], correctIndex: 1, explanation: 'Oligodendrocytes are the CNS equivalent of Schwann cells, producing myelin there.', difficulty: 'medium' },
  { id: 'ncc-8', type: 'mcq', question: "A neuron's cell body (cyton/soma) typically contains which organelle prominently, involved in protein synthesis?", options: ['Nissl granules (rough ER with ribosomes)', 'Chloroplasts', 'Cell wall', 'Vacuole'], correctIndex: 0, explanation: 'Nissl granules (rough endoplasmic reticulum with ribosomes) are prominent in the neuronal cell body, supporting protein synthesis.', difficulty: 'medium' },
  { id: 'ncc-9', type: 'mcq', question: 'Based on the number of processes extending from the cell body, a neuron with one axon and one dendrite is classified as:', options: ['Unipolar', 'Bipolar', 'Multipolar', 'Apolar'], correctIndex: 1, explanation: 'Bipolar neurons have exactly one axon and one dendrite extending from the cell body.', difficulty: 'medium' },
  { id: 'ncc-10', type: 'mcq', question: 'A neuron with one axon and multiple dendrites, such as most CNS neurons, is classified as:', options: ['Unipolar', 'Bipolar', 'Multipolar', 'Non-polar'], correctIndex: 2, explanation: 'Multipolar neurons, the most common type, have one axon and several dendrites.', difficulty: 'medium' },
  { id: 'ncc-11', type: 'mcq', question: "In a resting (non-conducting) neuron, the inside of the plasma membrane relative to the outside is:", options: ['More positively charged', 'More negatively charged', 'Exactly equal in charge', 'Impossible to measure'], correctIndex: 1, explanation: 'At resting potential, the inside of the axonal membrane is negatively charged relative to the outside.', difficulty: 'medium' },
  { id: 'ncc-12', type: 'mcq', question: 'The resting membrane potential of a typical neuron is maintained partly by unequal distribution of which ions, with sodium being more concentrated:', options: ['Outside the cell', 'Inside the cell', 'Equally on both sides', 'Only within the nucleus'], correctIndex: 0, explanation: 'Sodium ions are kept at higher concentration outside the neuron, maintained by the sodium-potassium pump.', difficulty: 'medium' },
  { id: 'ncc-13', type: 'mcq', question: 'The sodium-potassium pump, essential for maintaining resting potential, actively transports:', options: ['Only sodium ions, in one direction', 'Sodium ions out and potassium ions in, against their concentration gradients', 'Only potassium ions out', 'Chloride ions exclusively'], correctIndex: 1, explanation: 'The Na+/K+ pump actively moves Na+ out and K+ in, using ATP, against their respective gradients.', difficulty: 'medium' },
  { id: 'ncc-14', type: 'mcq', question: 'A stimulus that causes the neuronal membrane potential to become less negative (moving toward zero or positive) is said to cause:', options: ['Hyperpolarisation', 'Depolarisation', 'Repolarisation', 'No change'], correctIndex: 1, explanation: 'Depolarisation refers to the membrane potential becoming less negative, the first step of an action potential.', difficulty: 'medium' },
  { id: 'ncc-15', type: 'mcq', question: 'During the rising phase of an action potential, which ion channels open, allowing rapid influx of ions?', options: ['Potassium channels, allowing K+ influx', 'Voltage-gated sodium channels, allowing Na+ influx', 'Chloride channels only', 'Calcium channels exclusively, with no sodium involvement'], correctIndex: 1, explanation: 'Voltage-gated sodium channels open, allowing rapid Na+ influx that depolarises the membrane.', difficulty: 'medium' },
  { id: 'ncc-16', type: 'mcq', question: 'Repolarisation of the neuronal membrane, restoring the resting potential after an action potential, occurs mainly due to:', options: ['Continued sodium influx', 'Opening of potassium channels, allowing K+ efflux', 'Immediate reversal by the sodium-potassium pump alone', 'Calcium influx exclusively'], correctIndex: 1, explanation: 'Potassium channels open, allowing K+ to flow out, restoring the negative resting potential.', difficulty: 'medium' },
  { id: 'ncc-17', type: 'mcq', question: 'The brief period following an action potential during which a neuron cannot generate another action potential, regardless of stimulus strength, is called the:', options: ['Depolarisation phase', 'Absolute refractory period', 'Resting phase only', 'Saltatory phase'], correctIndex: 1, explanation: 'The absolute refractory period is a brief window where the neuron cannot fire again, ensuring unidirectional impulse propagation.', difficulty: 'medium' },
  { id: 'ncc-18', type: 'mcq', question: "The 'all or none' principle of nerve impulse conduction means that:", options: ['A stimulus below threshold produces a smaller, weaker action potential', 'Once threshold is reached, an action potential of fixed magnitude is generated, regardless of stimulus strength beyond threshold', 'Only very strong stimuli can ever generate an impulse', 'Impulses vary continuously in strength with stimulus intensity'], correctIndex: 1, explanation: "Action potentials are 'all or none' — once threshold is crossed, the response magnitude is fixed, not graded.", difficulty: 'medium' },
  { id: 'ncc-19', type: 'mcq', question: 'In myelinated neurons, the nerve impulse appears to jump from one node of Ranvier to the next. This is called:', options: ['Continuous conduction', 'Saltatory conduction', 'Reflex conduction', 'Synaptic conduction'], correctIndex: 1, explanation: 'Saltatory conduction, where impulses jump between nodes, allows myelinated axons to conduct impulses much faster.', difficulty: 'medium' },
  { id: 'ncc-20', type: 'mcq', question: 'The junction between the axon terminal of one neuron and the dendrite/cell body of another neuron is called a:', options: ['Node of Ranvier', 'Synapse', 'Nissl granule', 'Sarcomere'], correctIndex: 1, explanation: 'A synapse is the functional junction across which signals pass from one neuron to another.', difficulty: 'easy' },
  { id: 'ncc-21', type: 'mcq', question: 'At a chemical synapse, the signal is transmitted from one neuron to the next mainly via:', options: ['Direct flow of electric current', 'Release of neurotransmitter molecules across the synaptic cleft', 'Physical fusion of the two neurons', 'A gap junction only, with no chemical involved'], correctIndex: 1, explanation: 'Chemical synapses use neurotransmitters released into the synaptic cleft to relay signals.', difficulty: 'medium' },
  { id: 'ncc-22', type: 'mcq', question: 'At an electrical synapse, signal transmission occurs via:', options: ['Neurotransmitter diffusion across a wide synaptic cleft', 'Direct flow of electric current through gap junctions between adjacent neurons', 'Hormonal signalling only', 'No transmission occurs at all'], correctIndex: 1, explanation: 'Electrical synapses allow direct current flow through gap junctions, without a chemical intermediary.', difficulty: 'medium' },
  { id: 'ncc-23', type: 'mcq', question: 'Compared to electrical synapses, chemical synapses are generally:', options: ['Faster in signal transmission', 'Slower, due to the time needed for neurotransmitter release and diffusion', 'Identical in speed', 'Incapable of transmitting any signal'], correctIndex: 1, explanation: 'The steps of neurotransmitter release, diffusion, and receptor binding make chemical synapses slower than electrical ones.', difficulty: 'medium' },
  { id: 'ncc-24', type: 'mcq', question: 'Neurotransmitters are stored within the axon terminal in small membrane-bound sacs called:', options: ['Lysosomes', 'Synaptic vesicles', 'Nissl granules', 'Mitochondria'], correctIndex: 1, explanation: 'Synaptic vesicles store neurotransmitters, ready for release upon nerve impulse arrival.', difficulty: 'medium' },
  { id: 'ncc-25', type: 'mcq', question: 'The arrival of a nerve impulse at the axon terminal typically triggers the influx of which ion, initiating neurotransmitter release?', options: ['Sodium ions', 'Calcium ions', 'Chloride ions', 'Magnesium ions'], correctIndex: 1, explanation: 'Calcium influx at the axon terminal triggers synaptic vesicles to fuse with the membrane and release neurotransmitter.', difficulty: 'medium' },
  { id: 'ncc-26', type: 'mcq', question: 'The human nervous system is broadly divided into the:', options: ['Digestive and excretory systems', 'Central Nervous System (CNS) and Peripheral Nervous System (PNS)', 'Skeletal and muscular systems only', 'Endocrine system only'], correctIndex: 1, explanation: 'The CNS (brain and spinal cord) and PNS (nerves connecting CNS to the rest of the body) form the two major divisions.', difficulty: 'easy' },
  { id: 'ncc-27', type: 'mcq', question: 'The Central Nervous System (CNS) consists of the:', options: ['Cranial and spinal nerves only', 'Brain and spinal cord', 'Sympathetic and parasympathetic divisions only', 'Sense organs exclusively'], correctIndex: 1, explanation: 'The CNS comprises the brain and spinal cord, the primary integrating centres of the nervous system.', difficulty: 'easy' },
  { id: 'ncc-28', type: 'mcq', question: 'The Peripheral Nervous System (PNS) is composed of:', options: ['Only the brain', 'Cranial nerves and spinal nerves connecting the CNS to the rest of the body', 'Only the spinal cord', 'Only sensory receptors'], correctIndex: 1, explanation: 'The PNS consists of cranial and spinal nerves that relay information between the CNS and the body.', difficulty: 'medium' },
  { id: 'ncc-29', type: 'mcq', question: 'The human brain is broadly divided into which three major regions?', options: ['Cerebrum, cerebellum, and medulla only', 'Forebrain, midbrain, and hindbrain', 'Only left and right hemispheres', 'Only grey matter and white matter'], correctIndex: 1, explanation: 'The forebrain, midbrain, and hindbrain are the three major anatomical divisions of the brain.', difficulty: 'medium' },
  { id: 'ncc-30', type: 'mcq', question: 'The cerebrum, the largest part of the human forebrain, is primarily responsible for:', options: ['Basic reflex actions only', 'Higher cognitive functions like thinking, memory, and voluntary control', 'Heartbeat regulation exclusively', 'Balance and coordination exclusively'], correctIndex: 1, explanation: 'The cerebrum houses higher functions — reasoning, memory, sensory processing, and voluntary motor control.', difficulty: 'medium' },
  { id: 'ncc-31', type: 'mcq', question: 'The cerebrum is divided into two halves called the:', options: ['Lobes', 'Cerebral hemispheres', 'Ventricles', 'Meninges'], correctIndex: 1, explanation: 'The cerebrum is split into left and right cerebral hemispheres, connected by the corpus callosum.', difficulty: 'medium' },
  { id: 'ncc-32', type: 'mcq', question: 'The part of the brain located below the thalamus, playing a major role in regulating body temperature, hunger, and thirst, is the:', options: ['Cerebellum', 'Hypothalamus', 'Medulla oblongata', 'Pons'], correctIndex: 1, explanation: 'The hypothalamus regulates homeostatic functions like temperature, hunger, and thirst.', difficulty: 'medium' },
  { id: 'ncc-33', type: 'mcq', question: 'The thalamus functions mainly as a:', options: ['Relay/integration centre for sensory and motor signalling', 'Producer of digestive enzymes', 'Site of red blood cell formation', 'Structure that has no role in the nervous system'], correctIndex: 0, explanation: 'The thalamus relays and integrates sensory and motor information en route to the cerebral cortex.', difficulty: 'medium' },
  { id: 'ncc-34', type: 'mcq', question: 'The limbic system, involved in emotional responses, includes structures such as the:', options: ['Amygdala and hippocampus', 'Cochlea and retina', 'Sarcomeres', 'Nephrons'], correctIndex: 0, explanation: 'The amygdala and hippocampus are key limbic system structures involved in emotion and memory.', difficulty: 'medium' },
  { id: 'ncc-35', type: 'mcq', question: 'The midbrain is located between the:', options: ['Cerebrum and cerebellum', 'Forebrain and hindbrain', 'Spinal cord and PNS only', 'Eye and ear'], correctIndex: 1, explanation: 'The midbrain forms the connecting region between the forebrain and hindbrain.', difficulty: 'medium' },
  { id: 'ncc-36', type: 'mcq', question: 'The hindbrain comprises the:', options: ['Cerebrum, thalamus, and hypothalamus', 'Cerebellum, pons, and medulla oblongata', 'Only the spinal cord', 'Only cranial nerves'], correctIndex: 1, explanation: 'The hindbrain consists of the cerebellum, pons, and medulla oblongata.', difficulty: 'medium' },
  { id: 'ncc-37', type: 'mcq', question: 'The cerebellum is primarily responsible for:', options: ['Higher-order thinking and reasoning', 'Maintaining posture, balance, and coordinating fine voluntary movements', 'Producing hormones', 'Digestion of food'], correctIndex: 1, explanation: 'The cerebellum fine-tunes movement and maintains balance/posture.', difficulty: 'medium' },
  { id: 'ncc-38', type: 'mcq', question: 'The medulla oblongata, part of the hindbrain, regulates vital involuntary functions including:', options: ['Voluntary muscle movement only', 'Heart rate, breathing, and blood pressure', 'Vision processing exclusively', 'Long-term memory storage'], correctIndex: 1, explanation: 'The medulla houses centres controlling vital involuntary functions like heart rate, respiration, and blood pressure.', difficulty: 'medium' },
  { id: 'ncc-39', type: 'mcq', question: "The brain and spinal cord are protected by three membranous layers collectively called the:", options: ['Pleura', 'Meninges', 'Periosteum', 'Peritoneum'], correctIndex: 1, explanation: 'The meninges (dura mater, arachnoid mater, pia mater) protect the CNS.', difficulty: 'medium' },
  { id: 'ncc-40', type: 'mcq', question: 'The fluid that circulates within and around the brain and spinal cord, providing cushioning, is the:', options: ['Blood plasma', 'Cerebrospinal fluid (CSF)', 'Lymph', 'Synovial fluid'], correctIndex: 1, explanation: 'Cerebrospinal fluid cushions the CNS and helps maintain a stable chemical environment.', difficulty: 'medium' },
  { id: 'ncc-41', type: 'mcq', question: 'The spinal cord, in cross-section, shows an outer region of white matter and an inner region of:', options: ['Grey matter, containing cell bodies', 'More white matter only', 'Bone tissue', 'Cartilage'], correctIndex: 0, explanation: "The spinal cord's grey matter (cell bodies) is centrally located, surrounded by white matter (myelinated tracts) — the opposite arrangement of the cerebrum.", difficulty: 'medium' },
  { id: 'ncc-42', type: 'mcq', question: 'The total number of pairs of cranial nerves in humans is:', options: ['10', '12', '31', '24'], correctIndex: 1, explanation: 'Humans have 12 pairs of cranial nerves, arising directly from the brain.', difficulty: 'medium' },
  { id: 'ncc-43', type: 'mcq', question: 'The total number of pairs of spinal nerves in humans is:', options: ['12', '21', '31', '42'], correctIndex: 2, explanation: 'Humans have 31 pairs of spinal nerves, arising from the spinal cord.', difficulty: 'medium' },
  { id: 'ncc-44', type: 'mcq', question: 'The part of the PNS that controls voluntary actions, like skeletal muscle movement, is the:', options: ['Autonomic nervous system', 'Somatic nervous system', 'Sympathetic nervous system only', 'Enteric nervous system'], correctIndex: 1, explanation: 'The somatic nervous system governs voluntary movements via skeletal muscle innervation.', difficulty: 'medium' },
  { id: 'ncc-45', type: 'mcq', question: 'The part of the PNS that controls involuntary functions of internal organs is the:', options: ['Somatic nervous system', 'Autonomic nervous system', 'Only cranial nerves', 'Only spinal nerves'], correctIndex: 1, explanation: 'The autonomic nervous system regulates involuntary activities like heartbeat, digestion, and glandular secretion.', difficulty: 'medium' },
  { id: 'ncc-46', type: 'mcq', question: 'The autonomic nervous system is further divided into the:', options: ['Cranial and spinal divisions', 'Sympathetic and parasympathetic divisions', 'Somatic and skeletal divisions', 'Central and peripheral divisions'], correctIndex: 1, explanation: 'Sympathetic and parasympathetic divisions typically have opposing effects on target organs.', difficulty: 'medium' },
  { id: 'ncc-47', type: 'mcq', question: "The sympathetic nervous system generally prepares the body for 'fight or flight' responses by:", options: ['Slowing heart rate and promoting digestion', 'Increasing heart rate, dilating pupils, and diverting blood flow to skeletal muscles', 'Having no significant physiological effect', 'Only affecting the digestive system'], correctIndex: 1, explanation: 'Sympathetic activation triggers fight-or-flight changes: increased heart rate, pupil dilation, and blood redirected to muscles.', difficulty: 'medium' },
  { id: 'ncc-48', type: 'mcq', question: 'The parasympathetic nervous system generally promotes:', options: ['Fight or flight responses', "'Rest and digest' functions, like slowing heart rate and promoting digestion", 'Only pupil dilation', 'Increased sweating exclusively'], correctIndex: 1, explanation: 'Parasympathetic activity supports restful, restorative functions like digestion and lowered heart rate.', difficulty: 'medium' },
  { id: 'ncc-49', type: 'mcq', question: "A rapid, involuntary, and automatic response to a stimulus, bypassing conscious brain processing, is called a:", options: ['Voluntary action', 'Reflex action', 'Cognitive response', 'Hormonal response'], correctIndex: 1, explanation: 'Reflex actions are rapid, involuntary responses that often bypass the brain, being processed at the spinal cord level.', difficulty: 'easy' },
  { id: 'ncc-50', type: 'mcq', question: 'The neural pathway involved in a reflex action, from stimulus to response, is called the:', options: ['Synapse', 'Reflex arc', 'Sarcomere', 'Nephron loop'], correctIndex: 1, explanation: 'The reflex arc is the specific neural pathway a reflex action follows.', difficulty: 'medium' },
  { id: 'ncc-51', type: 'mcq', question: 'A typical reflex arc includes, in sequence:', options: ['Effector → CNS → receptor', 'Receptor → sensory neuron → CNS (often spinal cord) → motor neuron → effector', 'Only a receptor and an effector, with no neurons involved', 'Only the brain, with no spinal cord involvement'], correctIndex: 1, explanation: 'This is the standard sequence of a reflex arc, often bypassing the brain for speed.', difficulty: 'medium' },
  { id: 'ncc-52', type: 'mcq', question: 'The outermost, transparent, dome-shaped part of the eye, through which light first enters, is the:', options: ['Retina', 'Cornea', 'Iris', 'Sclera'], correctIndex: 1, explanation: 'The cornea is the transparent front layer through which light first enters the eye.', difficulty: 'easy' },
  { id: 'ncc-53', type: 'mcq', question: 'The coloured, muscular part of the eye that regulates the size of the pupil, controlling light entry, is the:', options: ['Cornea', 'Iris', 'Sclera', 'Lens'], correctIndex: 1, explanation: 'The iris adjusts pupil size to regulate how much light enters the eye.', difficulty: 'easy' },
  { id: 'ncc-54', type: 'mcq', question: 'The light-sensitive layer at the back of the eye, containing photoreceptor cells, is the:', options: ['Cornea', 'Retina', 'Sclera', 'Choroid'], correctIndex: 1, explanation: 'The retina contains rod and cone photoreceptors that detect light.', difficulty: 'easy' },
  { id: 'ncc-55', type: 'mcq', question: 'Photoreceptor cells responsible for vision in dim light (scotopic vision) are called:', options: ['Cones', 'Rods', 'Bipolar cells', 'Ganglion cells'], correctIndex: 1, explanation: 'Rods are highly sensitive to low light levels, enabling vision in dim conditions.', difficulty: 'medium' },
  { id: 'ncc-56', type: 'mcq', question: 'Photoreceptor cells responsible for colour vision in bright light (photopic vision) are called:', options: ['Rods', 'Cones', 'Horizontal cells', 'Amacrine cells'], correctIndex: 1, explanation: 'Cones detect colour and function best in bright light conditions.', difficulty: 'medium' },
  { id: 'ncc-57', type: 'mcq', question: 'The point on the retina where the optic nerve exits the eye, lacking any photoreceptors, is called the:', options: ['Fovea', 'Blind spot', 'Macula', 'Pupil'], correctIndex: 1, explanation: 'The blind spot, where the optic nerve exits, has no photoreceptors and thus cannot detect light.', difficulty: 'medium' },
  { id: 'ncc-58', type: 'mcq', question: 'The region of the retina with the highest concentration of cones, providing the sharpest visual acuity, is the:', options: ['Blind spot', 'Fovea (within the macula)', 'Sclera', 'Choroid'], correctIndex: 1, explanation: 'The fovea, densely packed with cones, provides the sharpest, most detailed vision.', difficulty: 'medium' },
  { id: 'ncc-59', type: 'mcq', question: 'The human ear is anatomically divided into:', options: ['Only the outer ear', 'Outer ear, middle ear, and inner ear', 'Only the inner ear and cochlea', 'Only the eardrum'], correctIndex: 1, explanation: 'The ear has three main regions: outer, middle, and inner ear.', difficulty: 'easy' },
  { id: 'ncc-60', type: 'mcq', question: 'The eardrum (tympanic membrane) separates the:', options: ['Outer ear from the middle ear', 'Middle ear from the inner ear', 'Cochlea from the semicircular canals', 'Retina from the lens'], correctIndex: 0, explanation: 'The tympanic membrane marks the boundary between the outer and middle ear.', difficulty: 'medium' },

  // ---- Assertion-Reason (25) ----
  { id: 'ncc-ar-1', type: 'assertion-reason', question: 'Assertion (A): Myelinated axons conduct nerve impulses faster than unmyelinated axons.\nReason (R): Myelin allows saltatory conduction, where the impulse jumps between nodes of Ranvier.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Saltatory conduction jumping between nodes is exactly why myelinated axons conduct impulses so much faster.', difficulty: 'medium' },
  { id: 'ncc-ar-2', type: 'assertion-reason', question: 'Assertion (A): At resting potential, the outside of a neuronal membrane is more negatively charged than the inside.\nReason (R): Sodium ions are more concentrated outside the cell, and potassium ions are more concentrated inside.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'At rest, the INSIDE (not outside) is more negative (A is false); R correctly describes the ion distribution that underlies this resting potential.', difficulty: 'medium' },
  { id: 'ncc-ar-3', type: 'assertion-reason', question: 'Assertion (A): Depolarisation of the neuronal membrane is caused by the influx of sodium ions.\nReason (R): Voltage-gated sodium channels open in response to a stimulus reaching threshold.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Sodium channel opening and the resulting Na+ influx directly cause the depolarisation described.', difficulty: 'medium' },
  { id: 'ncc-ar-4', type: 'assertion-reason', question: 'Assertion (A): The action potential follows the "all or none" principle.\nReason (R): Once threshold is reached, the amplitude of the action potential does not vary with stimulus strength beyond that point.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This fixed-amplitude response above threshold is exactly what defines the all-or-none principle.', difficulty: 'medium' },
  { id: 'ncc-ar-5', type: 'assertion-reason', question: 'Assertion (A): The absolute refractory period allows a neuron to fire multiple action potentials simultaneously in the same region.\nReason (R): During the refractory period, voltage-gated sodium channels are temporarily inactivated.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: "The refractory period actually PREVENTS (not allows) simultaneous firing in the same region (A is false); R correctly explains the sodium channel inactivation causing this.", difficulty: 'medium' },
  { id: 'ncc-ar-6', type: 'assertion-reason', question: 'Assertion (A): Chemical synapses transmit signals faster than electrical synapses.\nReason (R): Chemical synapses require neurotransmitter release, diffusion across the cleft, and receptor binding — steps that take measurable time.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Chemical synapses are actually SLOWER (not faster) than electrical synapses (A is false); R correctly explains why this delay occurs.', difficulty: 'medium' },
  { id: 'ncc-ar-7', type: 'assertion-reason', question: 'Assertion (A): Calcium ion influx at the axon terminal triggers neurotransmitter release.\nReason (R): Calcium influx causes synaptic vesicles to fuse with the presynaptic membrane, releasing their contents into the synaptic cleft.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This vesicle fusion mechanism triggered by calcium is exactly how neurotransmitter release is initiated.', difficulty: 'medium' },
  { id: 'ncc-ar-8', type: 'assertion-reason', question: 'Assertion (A): The cerebrum is responsible for basic involuntary functions like heart rate regulation.\nReason (R): The cerebrum is the seat of higher cognitive functions like thinking and voluntary control.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Heart rate regulation is actually controlled by the MEDULLA, not the cerebrum (A is false); R correctly describes the cerebrum\'s real function.', difficulty: 'medium' },
  { id: 'ncc-ar-9', type: 'assertion-reason', question: 'Assertion (A): The cerebellum plays a key role in maintaining balance and coordinating fine movements.\nReason (R): Damage to the cerebellum can result in loss of coordination and unsteady movement.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'These symptoms of cerebellar damage directly demonstrate its normal role in balance/coordination.', difficulty: 'medium' },
  { id: 'ncc-ar-10', type: 'assertion-reason', question: 'Assertion (A): The medulla oblongata controls vital involuntary functions such as breathing and heart rate.\nReason (R): The medulla is part of the forebrain.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 2, explanation: 'A is true, but R is false — the medulla is actually part of the HINDBRAIN, not the forebrain.', difficulty: 'medium' },
  { id: 'ncc-ar-11', type: 'assertion-reason', question: "Assertion (A): The hypothalamus plays a role in regulating body temperature and hunger.\nReason (R): The hypothalamus is located below the thalamus in the brain.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 1, explanation: 'Both statements are true, but R simply notes the anatomical location rather than explaining why the hypothalamus performs these regulatory functions.', difficulty: 'medium' },
  { id: 'ncc-ar-12', type: 'assertion-reason', question: 'Assertion (A): The meninges protect the brain and spinal cord.\nReason (R): The meninges consist of three layers: dura mater, arachnoid mater, and pia mater.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 1, explanation: 'Both statements are true, but R simply lists the meningeal layers rather than explaining the protective mechanism itself.', difficulty: 'medium' },
  { id: 'ncc-ar-13', type: 'assertion-reason', question: 'Assertion (A): Cerebrospinal fluid provides cushioning for the brain and spinal cord.\nReason (R): CSF circulates within and around the CNS, absorbing mechanical shocks.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This shock-absorbing circulation is exactly the mechanism by which CSF cushions the CNS.', difficulty: 'medium' },
  { id: 'ncc-ar-14', type: 'assertion-reason', question: 'Assertion (A): In the spinal cord, grey matter surrounds white matter, positioned peripherally.\nReason (R): The spinal cord\'s grey matter contains neuronal cell bodies, arranged centrally, with white matter (myelinated tracts) surrounding it.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The arrangement in the spinal cord is actually the OPPOSITE of what A claims — grey matter is central, white matter peripheral (A is false); R correctly describes the real arrangement.', difficulty: 'medium' },
  { id: 'ncc-ar-15', type: 'assertion-reason', question: 'Assertion (A): Humans have 31 pairs of cranial nerves.\nReason (R): Cranial nerves arise directly from the brain, while spinal nerves arise from the spinal cord.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Humans actually have 12 (not 31) pairs of cranial nerves — 31 is the number of SPINAL nerve pairs (A is false); R correctly distinguishes cranial from spinal nerve origins.', difficulty: 'medium' },
  { id: 'ncc-ar-16', type: 'assertion-reason', question: 'Assertion (A): The somatic nervous system controls involuntary functions of internal organs.\nReason (R): The autonomic nervous system controls involuntary functions, while the somatic nervous system controls voluntary skeletal muscle movement.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The somatic system actually controls VOLUNTARY (not involuntary) movement (A is false); R correctly distinguishes the two systems\' real roles.', difficulty: 'medium' },
  { id: 'ncc-ar-17', type: 'assertion-reason', question: "Assertion (A): Sympathetic nervous system activation increases heart rate and dilates pupils.\nReason (R): The sympathetic division prepares the body for 'fight or flight' responses.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Preparing the body for fight-or-flight is exactly why sympathetic activation increases heart rate and dilates pupils.', difficulty: 'medium' },
  { id: 'ncc-ar-18', type: 'assertion-reason', question: "Assertion (A): The parasympathetic nervous system generally opposes the effects of the sympathetic nervous system.\nReason (R): Parasympathetic activity promotes 'rest and digest' functions, such as slowing heart rate and stimulating digestion.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "These opposing 'rest and digest' effects are exactly why parasympathetic activity generally counters sympathetic effects.", difficulty: 'medium' },
  { id: 'ncc-ar-19', type: 'assertion-reason', question: 'Assertion (A): Reflex actions require conscious processing by the brain before a response occurs.\nReason (R): Reflex arcs are often processed at the level of the spinal cord, bypassing the brain for faster response.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Reflex actions actually do NOT require conscious brain processing (A is false) — R correctly explains why they can be so fast, via spinal-level processing.', difficulty: 'medium' },
  { id: 'ncc-ar-20', type: 'assertion-reason', question: 'Assertion (A): The cornea is the coloured part of the eye that controls pupil size.\nReason (R): The cornea is a transparent structure through which light first enters the eye.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The IRIS (not cornea) is the coloured, pupil-controlling structure (A is false); R correctly describes the cornea\'s real, transparent, light-entry function.', difficulty: 'medium' },
  { id: 'ncc-ar-21', type: 'assertion-reason', question: 'Assertion (A): Rods are responsible for colour vision in bright light.\nReason (R): Cones are the photoreceptors responsible for colour vision and function best in bright light.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Rods are actually for DIM light vision, not colour vision in bright light (A is false); R correctly assigns colour/bright-light vision to cones.', difficulty: 'medium' },
  { id: 'ncc-ar-22', type: 'assertion-reason', question: 'Assertion (A): The blind spot on the retina cannot detect light.\nReason (R): The blind spot is the region where the optic nerve exits the eye, lacking photoreceptors.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'The absence of photoreceptors at the optic nerve exit point is exactly why the blind spot cannot detect light.', difficulty: 'medium' },
  { id: 'ncc-ar-23', type: 'assertion-reason', question: 'Assertion (A): The fovea provides the sharpest visual acuity on the retina.\nReason (R): The fovea has the highest density of rod cells.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 2, explanation: 'A is true, but R is false — the fovea actually has the highest density of CONES (not rods), which is what gives it sharp acuity.', difficulty: 'medium' },
  { id: 'ncc-ar-24', type: 'assertion-reason', question: 'Assertion (A): The eardrum separates the outer ear from the middle ear.\nReason (R): The eardrum (tympanic membrane) vibrates in response to sound waves, transmitting vibrations further into the ear.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 1, explanation: 'Both statements are true, but R describes the eardrum\'s function rather than directly explaining WHY it is positioned as the outer-middle ear boundary.', difficulty: 'medium' },
  { id: 'ncc-ar-25', type: 'assertion-reason', question: 'Assertion (A): Neurotransmitters are stored in Nissl granules within the axon terminal.\nReason (R): Nissl granules are composed of rough endoplasmic reticulum and are found mainly in the cell body, not the axon terminal.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Neurotransmitters are actually stored in SYNAPTIC VESICLES (not Nissl granules) at the axon terminal (A is false); R correctly describes what Nissl granules really are and where they are found.', difficulty: 'hard' },

  // ---- Statement-based (25) ----
  { id: 'ncc-st-1', type: 'statement', question: 'Statement I: Dendrites receive incoming signals.\nStatement II: Axons carry impulses away from the cell body.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the roles of dendrites and axons.', difficulty: 'easy' },
  { id: 'ncc-st-2', type: 'statement', question: 'Statement I: Schwann cells form myelin in the CNS.\nStatement II: Oligodendrocytes form myelin in the PNS.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 1, explanation: 'Both statements have the roles swapped — Schwann cells myelinate the PNS, and oligodendrocytes myelinate the CNS.', difficulty: 'medium' },
  { id: 'ncc-st-3', type: 'statement', question: 'Statement I: At resting potential, the inside of the neuron is more negative than the outside.\nStatement II: The sodium-potassium pump helps maintain this resting potential.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe resting membrane potential and its maintenance.', difficulty: 'medium' },
  { id: 'ncc-st-4', type: 'statement', question: 'Statement I: Depolarisation is caused by potassium influx.\nStatement II: Repolarisation is caused by potassium efflux.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — depolarisation is caused by SODIUM influx, not potassium; Statement II correctly describes repolarisation.', difficulty: 'medium' },
  { id: 'ncc-st-5', type: 'statement', question: 'Statement I: The action potential follows the all-or-none principle.\nStatement II: Action potential amplitude increases with increasing stimulus strength above threshold.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — amplitude stays fixed above threshold, it does not increase further with stimulus strength.', difficulty: 'medium' },
  { id: 'ncc-st-6', type: 'statement', question: 'Statement I: Saltatory conduction occurs in myelinated neurons.\nStatement II: Saltatory conduction is slower than continuous conduction in unmyelinated axons.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — saltatory conduction is actually FASTER, not slower, than continuous conduction.', difficulty: 'medium' },
  { id: 'ncc-st-7', type: 'statement', question: 'Statement I: Chemical synapses use neurotransmitters to transmit signals.\nStatement II: Electrical synapses transmit signals via direct current flow through gap junctions.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the two types of synapses.', difficulty: 'medium' },
  { id: 'ncc-st-8', type: 'statement', question: 'Statement I: Calcium influx at the axon terminal triggers neurotransmitter release.\nStatement II: Neurotransmitters are stored in synaptic vesicles.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the mechanism of neurotransmitter release.', difficulty: 'medium' },
  { id: 'ncc-st-9', type: 'statement', question: 'Statement I: The CNS consists of the brain and spinal cord.\nStatement II: The PNS consists of cranial and spinal nerves.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the composition of the CNS and PNS.', difficulty: 'easy' },
  { id: 'ncc-st-10', type: 'statement', question: 'Statement I: The forebrain includes the cerebrum, thalamus, and hypothalamus.\nStatement II: The hindbrain includes the cerebellum, pons, and medulla.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the components of the forebrain and hindbrain.', difficulty: 'medium' },
  { id: 'ncc-st-11', type: 'statement', question: 'Statement I: The medulla oblongata regulates heart rate and breathing.\nStatement II: The medulla is part of the forebrain.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — the medulla is part of the hindbrain, not the forebrain.', difficulty: 'medium' },
  { id: 'ncc-st-12', type: 'statement', question: 'Statement I: The cerebellum is involved in higher-order cognitive functions like language.\nStatement II: The cerebellum coordinates balance and fine motor movements.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — higher cognitive functions like language are cerebral, not cerebellar; Statement II correctly describes the cerebellum\'s real role.', difficulty: 'medium' },
  { id: 'ncc-st-13', type: 'statement', question: 'Statement I: The meninges consist of three protective layers around the CNS.\nStatement II: Cerebrospinal fluid circulates within and around the brain and spinal cord.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe CNS protective structures.', difficulty: 'medium' },
  { id: 'ncc-st-14', type: 'statement', question: 'Statement I: Humans have 12 pairs of cranial nerves.\nStatement II: Humans have 31 pairs of spinal nerves.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly state the number of cranial and spinal nerve pairs in humans.', difficulty: 'medium' },
  { id: 'ncc-st-15', type: 'statement', question: 'Statement I: The somatic nervous system controls voluntary movements.\nStatement II: The autonomic nervous system controls involuntary functions of internal organs.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly distinguish the somatic and autonomic nervous systems.', difficulty: 'medium' },
  { id: 'ncc-st-16', type: 'statement', question: 'Statement I: The sympathetic nervous system slows heart rate and promotes digestion.\nStatement II: The parasympathetic nervous system slows heart rate and promotes digestion.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — the sympathetic system does the OPPOSITE (increases heart rate, suppresses digestion); Statement II correctly describes parasympathetic effects.', difficulty: 'medium' },
  { id: 'ncc-st-17', type: 'statement', question: 'Statement I: Reflex actions always require conscious processing in the cerebrum.\nStatement II: Reflex arcs can be processed rapidly at the spinal cord level.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — reflexes typically bypass conscious cerebral processing; Statement II correctly describes spinal-level reflex processing.', difficulty: 'medium' },
  { id: 'ncc-st-18', type: 'statement', question: 'Statement I: The cornea is transparent and allows light entry into the eye.\nStatement II: The iris regulates pupil size.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe these eye structures.', difficulty: 'easy' },
  { id: 'ncc-st-19', type: 'statement', question: 'Statement I: Rods are responsible for colour vision.\nStatement II: Cones function best in bright light and detect colour.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — rods are for dim-light, non-colour vision; Statement II correctly describes cones.', difficulty: 'medium' },
  { id: 'ncc-st-20', type: 'statement', question: 'Statement I: The blind spot is the region of the retina with the highest cone density.\nStatement II: The blind spot is where the optic nerve exits the eye, lacking photoreceptors.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — the blind spot has NO photoreceptors at all (the fovea has the highest cone density); Statement II correctly describes the blind spot.', difficulty: 'medium' },
  { id: 'ncc-st-21', type: 'statement', question: 'Statement I: The human ear is divided into outer, middle, and inner regions.\nStatement II: The tympanic membrane separates the outer ear from the middle ear.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe basic ear anatomy.', difficulty: 'medium' },
  { id: 'ncc-st-22', type: 'statement', question: 'Statement I: Bipolar neurons have one axon and multiple dendrites.\nStatement II: Multipolar neurons have one axon and multiple dendrites.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — bipolar neurons have exactly ONE dendrite (not multiple); Statement II correctly describes multipolar neurons.', difficulty: 'medium' },
  { id: 'ncc-st-23', type: 'statement', question: 'Statement I: Nissl granules are found prominently in the neuronal cell body.\nStatement II: Nissl granules are composed of rough endoplasmic reticulum with ribosomes.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe Nissl granules and their location.', difficulty: 'medium' },
  { id: 'ncc-st-24', type: 'statement', question: 'Statement I: The hypothalamus regulates body temperature and hunger.\nStatement II: The thalamus acts as a relay/integration centre for sensory and motor signals.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the functions of the hypothalamus and thalamus.', difficulty: 'medium' },
  { id: 'ncc-st-25', type: 'statement', question: 'Statement I: The limbic system includes the amygdala and hippocampus.\nStatement II: The limbic system has no role in emotional responses.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — the limbic system is in fact central to emotional processing.', difficulty: 'medium' },

  // ---- "How many of the following are correct" (12) ----
  { id: 'ncc-hm-1', type: 'statement', question: 'How many of the following are parts of a typical neuron?\nDendrites, Axon, Cell body (soma), Sarcomere', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Dendrites, axon, and cell body are genuine neuron parts; a sarcomere is a muscle structure, unrelated to neurons.', difficulty: 'medium' },
  { id: 'ncc-hm-2', type: 'statement', question: 'How many of the following are true regarding resting membrane potential?\nThe inside of the neuron is more negative than the outside, Sodium is more concentrated outside the cell, Potassium is more concentrated outside the cell, The sodium-potassium pump helps maintain this potential', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first, second, and fourth statements are correct; potassium is actually more concentrated INSIDE (not outside) the cell.', difficulty: 'medium' },
  { id: 'ncc-hm-3', type: 'statement', question: 'How many of the following occur during a typical action potential, in some sequence?\nDepolarisation via sodium influx, Repolarisation via potassium efflux, A brief refractory period, Permanent loss of the resting potential', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three are genuine sequential events of an action potential; the resting potential is restored, not permanently lost.', difficulty: 'medium' },
  { id: 'ncc-hm-4', type: 'statement', question: 'How many of the following are types of synapses?\nChemical synapse, Electrical synapse, Sarcomere synapse, Reflex synapse', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Chemical and electrical synapses are the two genuine, recognised types; "sarcomere synapse" and "reflex synapse" are not real synapse classifications.', difficulty: 'medium' },
  { id: 'ncc-hm-5', type: 'statement', question: 'How many of the following are components of the forebrain?\nCerebrum, Thalamus, Hypothalamus, Medulla oblongata', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Cerebrum, thalamus, and hypothalamus are forebrain components; the medulla is part of the hindbrain.', difficulty: 'medium' },
  { id: 'ncc-hm-6', type: 'statement', question: 'How many of the following are components of the hindbrain?\nCerebellum, Pons, Medulla oblongata, Thalamus', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Cerebellum, pons, and medulla are hindbrain components; the thalamus belongs to the forebrain.', difficulty: 'medium' },
  { id: 'ncc-hm-7', type: 'statement', question: 'How many of the following are layers of the meninges?\nDura mater, Arachnoid mater, Pia mater, Sclera', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Dura, arachnoid, and pia mater are the three meningeal layers; the sclera is part of the eye, unrelated to the meninges.', difficulty: 'medium' },
  { id: 'ncc-hm-8', type: 'statement', question: 'How many of the following are true regarding the autonomic nervous system?\nIt has sympathetic and parasympathetic divisions, It controls involuntary functions, The sympathetic division promotes fight-or-flight, It controls all voluntary skeletal muscle movement', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; voluntary skeletal muscle movement is controlled by the SOMATIC (not autonomic) nervous system.', difficulty: 'medium' },
  { id: 'ncc-hm-9', type: 'statement', question: 'How many of the following are components of a typical reflex arc?\nReceptor, Sensory neuron, Motor neuron, Effector', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four are genuine components of a standard reflex arc pathway.', difficulty: 'easy' },
  { id: 'ncc-hm-10', type: 'statement', question: 'How many of the following are structures/parts of the human eye?\nCornea, Iris, Retina, Cochlea', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Cornea, iris, and retina are eye structures; the cochlea is part of the ear.', difficulty: 'medium' },
  { id: 'ncc-hm-11', type: 'statement', question: 'How many of the following are structures/parts of the human ear?\nCochlea, Tympanic membrane (eardrum), Semicircular canals, Fovea', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Cochlea, eardrum, and semicircular canals are ear structures; the fovea is part of the eye (retina).', difficulty: 'medium' },
  { id: 'ncc-hm-12', type: 'statement', question: 'How many of the following are true regarding rods and cones?\nRods function well in dim light, Cones detect colour, Rods are concentrated at the fovea, Cones function best in bright light', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first, second, and fourth statements are correct; the fovea is actually densely packed with CONES (not rods).', difficulty: 'medium' },
];